CREATE TABLE public.wisata (id serial PRIMARY KEY, name text, category text, image text, location text, description text, partner boolean DEFAULT false, active boolean DEFAULT true, phone text, website text, opening_hours text, facilities text, maps_embed_url text, google_maps_url text, instagram text, photos text, slug text UNIQUE, updated_at timestamptz DEFAULT now(), rating numeric DEFAULT 0, entry_fee integer DEFAULT 0, created_at timestamptz DEFAULT now());
CREATE TABLE public.kuliner (id serial PRIMARY KEY, name text, category text, image text, location text, description text, featured boolean DEFAULT false, hours text, active boolean DEFAULT true, phone text, google_maps_url text, maps_embed_url text, price_range text, instagram text, website text, facilities text, photos text, reservasi_enabled boolean DEFAULT false, slug text UNIQUE, updated_at timestamptz DEFAULT now(), rating numeric DEFAULT 0, created_at timestamptz DEFAULT now());
CREATE TABLE public.penginapan (id serial PRIMARY KEY, name text, category text, rating numeric DEFAULT 0, price_per_night integer DEFAULT 0, image text, location text, description text, featured boolean DEFAULT false, active boolean DEFAULT true, instagram text, booking_enabled boolean DEFAULT false, slug text UNIQUE, updated_at timestamptz DEFAULT now(), amenities text[] DEFAULT '{}', created_at timestamptz DEFAULT now());
CREATE TABLE public.events (id serial PRIMARY KEY, name text, title text, category text, date text, date_end text, time_start text, time_end text, location text, image text, banner_image text, description text, price integer DEFAULT 0, organizer text, organizer_ig text, featured boolean DEFAULT false, active boolean DEFAULT true, maps_url text, allow_voucher boolean DEFAULT false, crew_active boolean DEFAULT false, guest_stars jsonb, prohibited_items jsonb, rundown jsonb, transportation_info jsonb, menu_items jsonb, payment_info jsonb, slug text UNIQUE, visitors integer DEFAULT 0, service_fee_percent numeric DEFAULT 0, updated_at timestamptz DEFAULT now(), created_at timestamptz DEFAULT now());
CREATE TABLE public.event_tickets (id serial PRIMARY KEY, sold integer DEFAULT 0, event_id integer, name text, description text, price integer DEFAULT 0, quota integer DEFAULT 0, sale_start text, sale_end text, sort_order integer DEFAULT 0, active boolean DEFAULT true, created_at timestamptz DEFAULT now());
CREATE TABLE public.berita (id serial PRIMARY KEY, title text, category text, image text, content text, summary text, author text, location text, featured boolean DEFAULT false, active boolean DEFAULT true, status text, submitter_name text, submitter_email text, event_date text, photo_source text, source_name text, source_url text, published_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), slug text UNIQUE, created_at timestamptz DEFAULT now());
CREATE TABLE public.banners (id serial PRIMARY KEY, title text, link text, image text, sort_order integer DEFAULT 0, active boolean DEFAULT true, updated_at timestamptz DEFAULT now(), subtitle text, description text, category text, btn_text text, accent text, created_at timestamptz DEFAULT now());
CREATE TABLE public.perlombaan (id serial PRIMARY KEY, name text, category text, date text, location text, image text, description text, prize integer DEFAULT 0, organizer text, fee integer DEFAULT 0, max_peserta integer DEFAULT 0, featured boolean DEFAULT false, active boolean DEFAULT true, created_at timestamptz DEFAULT now());
CREATE TABLE public.digital_services (id serial PRIMARY KEY, title text, description text, price integer DEFAULT 0, category text, image text, whatsapp text, featured boolean DEFAULT false, active boolean DEFAULT true, updated_at timestamptz DEFAULT now(), created_at timestamptz DEFAULT now());
CREATE TABLE public.price_list (id serial PRIMARY KEY, item text, price integer DEFAULT 0, category text, description text, sort_order integer DEFAULT 0, active boolean DEFAULT true, updated_at timestamptz DEFAULT now(), created_at timestamptz DEFAULT now());
CREATE TABLE public.transportasi (id serial PRIMARY KEY, name text, type text, kode text, asal text, tujuan text, via text, tarif integer DEFAULT 0, jam text, frekuensi text, description text, active boolean DEFAULT true, updated_at timestamptz DEFAULT now(), created_at timestamptz DEFAULT now());
CREATE TABLE public.vouchers (id serial PRIMARY KEY, title text, code text, type text, discount_type text, discount_value integer DEFAULT 0, min_purchase integer DEFAULT 0, expiry_date text, description text, active boolean DEFAULT true, mitra_id integer, updated_at timestamptz DEFAULT now(), kuliner_id integer, applicable_type text, required_points integer DEFAULT 0, created_at timestamptz DEFAULT now());
CREATE TABLE public.talents (id serial PRIMARY KEY, name text, role text, category text, tagline text, instagram text, tags text[] DEFAULT '{}', verified boolean DEFAULT false, featured boolean DEFAULT false, bio text, wa text, photo text, sort_order integer DEFAULT 0, active boolean DEFAULT true, updated_at timestamptz DEFAULT now(), created_at timestamptz DEFAULT now());
CREATE TABLE public.influencers (id serial PRIMARY KEY, name text, handle text, instagram text, tiktok text, verified boolean DEFAULT false, color text, color2 text, niches text[] DEFAULT '{}', location text, rating numeric DEFAULT 0, rate text, bio text, photos text[] DEFAULT '{}', active boolean DEFAULT true, sort_order integer DEFAULT 0, updated_at timestamptz DEFAULT now(), created_at timestamptz DEFAULT now());
CREATE TABLE public.site_settings (key text PRIMARY KEY, value text, updated_at timestamptz DEFAULT now());
CREATE TABLE public.promo_banners (id serial PRIMARY KEY, image text, link text, sort_order integer DEFAULT 0, active boolean DEFAULT true, updated_at timestamptz DEFAULT now(), created_at timestamptz DEFAULT now());
CREATE TABLE public.partners (id serial PRIMARY KEY, name text, color text, sort_order integer DEFAULT 0, active boolean DEFAULT true, updated_at timestamptz DEFAULT now(), created_at timestamptz DEFAULT now());
CREATE TABLE public.kamus_sunda (id serial PRIMARY KEY, sunda text, indonesia text, latin text, category text, level text, example text, active boolean DEFAULT true, updated_at timestamptz DEFAULT now(), created_at timestamptz DEFAULT now());

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['wisata','kuliner','penginapan','events','event_tickets','berita','banners','perlombaan','digital_services','price_list','transportasi','vouchers','talents','influencers','site_settings','promo_banners','partners','kamus_sunda'] LOOP
    EXECUTE format('GRANT SELECT ON public.%I TO anon, authenticated', t);
    EXECUTE format('GRANT ALL ON public.%I TO service_role', t);
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    IF t = 'site_settings' THEN
      EXECUTE format('CREATE POLICY "Public can read %s" ON public.%I FOR SELECT TO anon, authenticated USING (true)', t, t);
    ELSIF t = 'berita' THEN
      EXECUTE format('CREATE POLICY "Public can read %s" ON public.%I FOR SELECT TO anon, authenticated USING (active = true AND coalesce(status,''approved'') = ''approved'')', t, t);
    ELSE
      EXECUTE format('CREATE POLICY "Public can read %s" ON public.%I FOR SELECT TO anon, authenticated USING (active = true)', t, t);
    END IF;
  END LOOP;
END $$;